import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_gelu_cuda = load_inline(
    name="gelu_cuda_fused",
    cpp_sources="",
    cuda_sources=r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void gelu_tanh_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int64_t n
) {
    const int64_t stride = static_cast<int64_t>(blockDim.x) * gridDim.x;
    int64_t i = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;

    constexpr float kSqrtTwoOverPi = 0.7978845608028654f;
    constexpr float kCoeff = 0.044715f;

    for (; i < n; i += stride) {
        const float v = x[i];
        const float v2 = v * v;
        const float v3 = v2 * v;
        const float inner = kSqrtTwoOverPi * (v + kCoeff * v3);
        out[i] = 0.5f * v * (1.0f + tanhf(inner));
    }
}

torch::Tensor gelu(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");

    auto x_contiguous = x.contiguous();
    auto out = torch::empty_like(x_contiguous);
    const int64_t n = x_contiguous.numel();

    if (n == 0) {
        return out;
    }

    const c10::cuda::CUDAGuard device_guard(x_contiguous.device());
    constexpr int threads = 256;
    const int blocks = static_cast<int>(
        std::min<int64_t>((n + threads - 1) / threads, 65535)
    );

    gelu_tanh_kernel<<<
        blocks,
        threads,
        0,
        at::cuda::getDefaultCUDAStream()
    >>>(
        x_contiguous.data_ptr<float>(),
        out.data_ptr<float>(),
        n
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gelu", &gelu, "Fused tanh GELU CUDA kernel");
}
""",
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        return _gelu_cuda.gelu(x)

